UPDATE rag_entity_cooccurrence c SET co_count = c.co_count - v.delta FROM (VALUES
(#{p.entityA}::bigint, #{p.entityB}::bigint, #{p.coCount}::int)
) AS v(entity_a, entity_b, delta) WHERE c.entity_a = v.entity_a AND c.entity_b = v.entity_b AND c.user_id = #{userId} AND (#{teamId,jdbcType=BIGINT} IS NULL AND c.team_id IS NULL OR c.team_id = #{teamId,jdbcType=BIGINT})

